(()=>{document.querySelectorAll(".markdown pre").forEach(e=>{const o=e.querySelector("code");if(!o||e.closest(".jw-code-block"))return;const s=document.createElement("div");s.className="jw-code-block",e.before(s),s.append(e);const t=document.createElement("button");t.type="button",t.className="jw-code-copy",t.textContent="复制",t.setAttribute("aria-label","复制代码");const n=document.createElement("span");n.className="jw-visually-hidden",n.setAttribute("role","status"),s.append(t,n);let i;t.addEventListener("click",async()=>{clearTimeout(i);try{await navigator.clipboard.writeText(o.textContent),t.textContent="已复制",n.textContent="代码已复制"}catch{t.textContent="复制失败",n.textContent="复制失败，请选择代码后手动复制"}i=setTimeout(()=>{t.textContent="复制",n.textContent=""},2e3)})})})()